link.script:
window.jQuery = window.$ = function(handler) {
    if (typeof handler === 'function') {
        window._jqQueue = window._jqQueue || [];
        window._jqQueue.push(handler);
    }
    return window.jQuery;
};
window.jQuery.ready = window.jQuery;

body.script:
(function () {
    var leakedPixelPattern = /TT-[A-Z0-9]+-Web-Tag-Pixel_Setup/;

    function removeLeakedPixelText() {
        var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        var leakedNodes = [];

        while (walker.nextNode()) {
            if (leakedPixelPattern.test(walker.currentNode.textContent)) {
                leakedNodes.push(walker.currentNode);
            }
        }

        leakedNodes.forEach(function (node) {
            var parent = node.parentNode;
            if (!parent) return;

            if (parent !== document.body && parent.textContent.trim() === node.textContent.trim()) {
                parent.remove();
                return;
            }

            node.textContent = node.textContent.replace(leakedPixelPattern, '').trim();
        });
    }

    removeLeakedPixelText();
    document.addEventListener('DOMContentLoaded', removeLeakedPixelText);
    window.addEventListener('load', removeLeakedPixelText);

    if (typeof MutationObserver !== 'undefined') {
        var observer = new MutationObserver(removeLeakedPixelText);
        observer.observe(document.body, { childList: true, subtree: true });
        setTimeout(function () { observer.disconnect(); }, 15000);
    }
})();
